import {
  BoxGeometry,
  Material,
  Mesh,
  MeshBasicMaterial,
  Object3D,
} from '@iwsdk/core';
import { DEFENSE_BUTTONS } from './level-config.js';

/**
 * Repair button rigs.
 *
 * The visible glyph is a designed asset: `gltf/defense-button-repair.glb`
 * (service wrench, signal-green family), generated by
 * `npm run export-assets`. It carries one merged `button-icon` mesh — white
 * dielectric PBR (roughness 0.5, metalness 0) with the colour zones baked
 * into vertex colors, so the icon sits in the same material family as the
 * wall and cannons.
 *
 * State visuals stay runtime-side and cheap: DefenseButtonSystem shrinks +
 * glows the repair icon of a repairing unit — scale writes on the icon mesh
 * plus one emissive-intensity scalar on the icon's own material clone
 * (cloned below so the glow hits one button, never the shared prototype);
 * the hit proxy never changes. The glyph needs no shadow participation —
 * both shadow flags are forced off below.
 *
 * The invisible hit proxy is a box that renders nothing (colorWrite off) yet
 * stays raycastable — object.visible is what raycasters key on, not material
 * color. The box is deliberately larger than the glyph so a thumb or XR ray
 * never has to land on the icon itself, and is trimmed in X so neighbouring
 * slots never overlap.
 */

/** Shared invisible-hit-proxy geometry — renders nothing, hits all. */
const PROXY_GEOMETRY = new BoxGeometry(
  DEFENSE_BUTTONS.proxyRepair.x,
  DEFENSE_BUTTONS.proxyRepair.y,
  DEFENSE_BUTTONS.proxyRepair.z,
);
const PROXY_MATERIAL = new MeshBasicMaterial({
  colorWrite: false,
  depthWrite: false,
  transparent: true,
});

/**
 * One repair button rig: a clone of the icon's GLB prototype (the
 * `button-icon` mesh keeps its baked vertex colors; geometry stays shared)
 * plus the invisible hit proxy, centred on its mount point facing +Z. The
 * icon's material is cloned per rig — DefenseButtonSystem drives the repair
 * glow through per-button emissiveIntensity, which must not touch the
 * shared prototype material. The caller creates the transform entity, adds
 * RayInteractable + DefenseButton and owns placement (battle-setup);
 * DefenseButtonSystem resolves the icon mesh by name for its per-frame
 * state writes.
 */
export function createRepairButtonRig(prototype: Object3D): Object3D {
  const rig = prototype.clone(true);
  rig.name = 'defense-button-repair';
  rig.traverse((child: Object3D) => {
    if ((child as Mesh).isMesh) {
      child.castShadow = false;
      child.receiveShadow = false;
    }
  });

  const icon = rig.getObjectByName('button-icon') as Mesh | null;
  if (icon) icon.material = (icon.material as Material).clone();

  const proxy = new Mesh(PROXY_GEOMETRY, PROXY_MATERIAL);
  proxy.name = 'button-proxy';
  proxy.castShadow = false;
  proxy.receiveShadow = false;

  rig.add(proxy);
  return rig;
}
